def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    hdiv = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    vdiv = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def intervals(n, divs):
        out, start = [], 0
        for d in divs:
            if start < d:
                out.append((start, d))
            start = d + 1
        if start < n:
            out.append((start, n))
        return out

    rows, cols = intervals(h, hdiv), intervals(w, vdiv)
    source = None
    for r0, r1 in rows:
        for c0, c1 in cols:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            if any(v != bg for row in tile for v in row):
                source = tile
                break
        if source is not None:
            break
    out = [row[:] for row in grid]
    if source is None:
        return out
    for r0, r1 in rows:
        for c0, c1 in cols:
            for dr in range(r1-r0):
                for dc in range(c1-c0):
                    out[r0+dr][c0+dc] = source[dr][dc]
    return out
